const menuToggle=document.querySelector(".menu-toggle"),mainMenu=document.getElementById("mainMenu"),overlay=document.createElement("div");overlay.className="menu-overlay";document.body.appendChild(overlay);function setMenu(e){mainMenu.classList.toggle("open",e);menuToggle.classList.toggle("open",e);overlay.classList.toggle("show",e);document.body.classList.toggle("menu-open",e);menuToggle.setAttribute("aria-expanded",e);menuToggle.setAttribute("aria-label",e?"Мәзірді жабу":"Мәзірді ашу")}menuToggle.addEventListener("click",function(){setMenu(!mainMenu.classList.contains("open"))});overlay.addEventListener("click",function(){setMenu(!1)});mainMenu.querySelectorAll("a").forEach(function(e){e.addEventListener("click",function(){setMenu(!1)})});document.addEventListener("keydown",function(e){"Escape"===e.key&&setMenu(!1)});
